import * as T from './three.module.js';
// Simplified painter renderer for machines where a WebGL context is unavailable.
export class SoftwareRenderer {
constructor(canvas){this.canvas=canvas;this.ctx=canvas.getContext('2d');this.shadowMap={};this.v=new T.Vector3();this.m=new T.Matrix4();}
setPixelRatio(){}setSize(w,h){this.canvas.width=w;this.canvas.height=h;}
render(scene,camera){const ctx=this.ctx,w=this.canvas.width,h=this.canvas.height;if(!ctx)return;scene.updateMatrixWorld();camera.updateMatrixWorld();camera.matrixWorldInverse.copy(camera.matrixWorld).invert();const bg=scene.background,light=scene.children.find(o=>o.isHemisphereLight),day=T.MathUtils.clamp((light.intensity-.32)/1.8,0,1);const gradient=ctx.createLinearGradient(0,0,0,h*.66);gradient.addColorStop(0,'#'+bg.clone().multiplyScalar(.72).getHexString());gradient.addColorStop(1,'#'+bg.clone().lerp(new T.Color('#e5d7ac'),day*.23).getHexString());ctx.fillStyle=gradient;ctx.fillRect(0,0,w,h);
const chunk=scene.children.find(o=>o.userData.b&&o.userData.index===Math.floor((o.position.z||0)/120));const ground=(chunk??scene.children.find(o=>o.userData.b))?.children[0]?.material.color??new T.Color('#8eaa65');const horizon=new T.Vector3(0,0,-5000).applyMatrix4(camera.projectionMatrix.clone().multiply(camera.matrixWorldInverse));const hy=T.MathUtils.clamp((1-horizon.y)*h/2,h*.2,h*.8);ctx.fillStyle='#'+ground.clone().multiplyScalar(.3+day*.7).getHexString();ctx.fillRect(0,hy,w,h-hy);
const shapes=[],temp=new T.Vector3(),projection=camera.projectionMatrix;const project=(x,y,z,m)=>{temp.set(x,y,z).applyMatrix4(m);const vx=temp.x,vy=temp.y,vz=temp.z;temp.applyMatrix4(projection);return {x:(temp.x+1)*w/2,y:(1-temp.y)*h/2,z:temp.z,vx,vy,vz,d:-vz};};
const clip=points=>{const out=[];for(let i=0;i<points.length;i++){const a=points[i],b=points[(i+1)%points.length],ia=a.vz<-.16,ib=b.vz<-.16;if(ia)out.push(a);if(ia!==ib){const f=(-.16-a.vz)/(b.vz-a.vz),v=new T.Vector3(T.MathUtils.lerp(a.vx,b.vx,f),T.MathUtils.lerp(a.vy,b.vy,f),-.16).applyMatrix4(projection);out.push({x:(v.x+1)*w/2,y:(1-v.y)*h/2,d:.16});}}return out;};
const add=(points,col,extra={})=>{const clipped=clip(points);if(clipped.length<3)return;if(clipped.every(p=>p.x<0)||clipped.every(p=>p.x>w)||clipped.every(p=>p.y<0)||clipped.every(p=>p.y>h))return;shapes.push({points:clipped,d:points.reduce((a,p)=>a+p.d,0)/points.length,col,...extra});};
scene.traverse(o=>{if(!o.isMesh||!o.visible)return;const geo=o.geometry,material=Array.isArray(o.material)?o.material[0]:o.material;if(!material?.color||material.opacity===0)return;if(material.map&&material.isMeshBasicMaterial)return;if(!geo.boundingSphere)geo.computeBoundingSphere();const center=geo.boundingSphere.center.clone().applyMatrix4(o.matrixWorld);const d=center.distanceTo(camera.position),radius=geo.boundingSphere.radius*Math.max(o.scale.x,o.scale.y,o.scale.z);if(d>1400+radius)return;if(d>620&&!o.userData.backdrop&&geo.type!=='SphereGeometry')return;const cv=center.clone().applyMatrix4(camera.matrixWorldInverse);if(cv.z>radius)return;const c=center.clone().project(camera);if(Math.abs(c.x)>2.4+radius/Math.max(d,1)||Math.abs(c.y)>2.8+radius/Math.max(d,1))return;this.m.multiplyMatrices(camera.matrixWorldInverse,o.matrixWorld);const m=this.m,fade=T.MathUtils.clamp((d-150)/900,0,.97),col=material.color.clone().multiplyScalar(material.isMeshBasicMaterial?1:.29+day*.76).lerp(bg,fade),type=geo.type,alpha=material.transparent?material.opacity:1;
if(type==='SphereGeometry'){if(cv.z>-.2)return;const p=project(0,0,0,m);const scale=new T.Vector3();o.getWorldScale(scale);const rad=geo.parameters.radius*scale.x*projection.elements[0]*w/(2*-cv.z);if(rad<.45)return;shapes.push({kind:'ellipse',x:p.x,y:p.y,rx:rad,ry:rad*scale.y/scale.x,d,col,alpha});return;}
if(type==='BoxGeometry'){const p=geo.parameters;if(p.width>500)return;const x=p.width/2,y=p.height/2,z=p.depth/2,vs=[[-x,-y,-z],[x,-y,-z],[x,y,-z],[-x,y,-z],[-x,-y,z],[x,-y,z],[x,y,z],[-x,y,z]].map(a=>project(...a,m));for(const [face,shade] of [[[0,3,2,1],.82],[[4,5,6,7],.94],[[0,4,7,3],.72],[[1,2,6,5],.9],[[3,7,6,2],1.12],[[0,1,5,4],.6]]){const pts=face.map(i=>vs[i]);if(pts.every(p=>p.vz>-.16))continue;const cross=(pts[1].x-pts[0].x)*(pts[2].y-pts[0].y)-(pts[1].y-pts[0].y)*(pts[2].x-pts[0].x);if(pts.every(p=>p.vz<-.16)&&cross>0)continue;add(pts,col.clone().multiplyScalar(shade),{alpha});}return;}
const pa=geo.attributes.position,index=geo.index;if(!pa)return;const isRibbon=type==='BufferGeometry'&&!o.userData.backdrop;const terrain=o.userData.terrain||isRibbon;const count=index?index.count:pa.count;const normal=geo.attributes.normal;
for(let j=0;j<count;j+=3){const pts=[];let ny=0;for(let k=0;k<3;k++){const i=index?index.getX(j+k):j+k;pts.push(project(pa.getX(i),pa.getY(i),pa.getZ(i),m));if(normal)ny+=normal.getY(i);}if(pts.every(p=>p.vz>-.16))continue;const cross=(pts[1].x-pts[0].x)*(pts[2].y-pts[0].y)-(pts[1].y-pts[0].y)*(pts[2].x-pts[0].x);if(!terrain&&!o.userData.backdrop&&material.side!==T.DoubleSide&&pts.every(p=>p.vz<-.16)&&cross>0)continue;const shade=type==='ExtrudeGeometry'?.84+Math.max(0,ny/3)*.22:1;add(pts,col.clone().multiplyScalar(shade),{alpha,terrain,layer:o.userData.terrain?-1:terrain?pa.getY(0):0,backdrop:o.userData.backdrop});}
});
shapes.sort((a,b)=>a.backdrop!==b.backdrop?(a.backdrop?-1:b.backdrop?1:0):a.terrain&&b.terrain?(a.layer-b.layer||b.d-a.d):a.terrain?-1:b.terrain?1:b.d-a.d);
for(const s of shapes){ctx.globalAlpha=s.alpha??1;const color='#'+s.col.getHexString();if(s.kind==='ellipse'){if(s.rx>4){const gr=ctx.createRadialGradient(s.x-s.rx*.3,s.y-s.ry*.35,0,s.x,s.y,Math.max(s.rx,s.ry));gr.addColorStop(0,'#'+s.col.clone().multiplyScalar(1.18).getHexString());gr.addColorStop(1,'#'+s.col.clone().multiplyScalar(.68).getHexString());ctx.fillStyle=gr;}else ctx.fillStyle=color;ctx.beginPath();ctx.ellipse(s.x,s.y,s.rx,s.ry,0,0,Math.PI*2);ctx.fill();}else{ctx.fillStyle=color;ctx.beginPath();s.points.forEach((p,i)=>i?ctx.lineTo(p.x,p.y):ctx.moveTo(p.x,p.y));ctx.closePath();ctx.fill();if((s.alpha??1)===1){ctx.strokeStyle=color;ctx.lineWidth=.45;ctx.stroke();}}}ctx.globalAlpha=1;
scene.traverse(o=>{if(!o.isPoints||o.material.opacity<.05)return;const attr=o.geometry.attributes.position,m=new T.Matrix4().multiplyMatrices(camera.matrixWorldInverse,o.matrixWorld);ctx.fillStyle='rgba(236,243,244,'+o.material.opacity+')';for(let i=0;i<attr.count;i+=2){const p=project(attr.getX(i),attr.getY(i),attr.getZ(i),m);if(p.vz>-.2)continue;ctx.fillRect(p.x,p.y,o.material.size>.15?2:1,o.material.size>.15?2:8);}});
}
}
